import * as pdfjs from './pdf.min.mjs';
pdfjs.GlobalWorkerOptions.workerSrc='./pdf.worker.min.mjs';
const $=id=>document.getElementById(id);let seed=431,canvases=[];
function random(){seed=(Math.imul(1664525,seed)+1013904223)>>>0;return seed/4294967296}
async function render(){await Promise.all(["Caveat","Patrick","Kalam"].map(f=>document.fonts.load(`28px ${f}`)));await document.fonts.ready;seed=Number($('pages').dataset.seed||431);const size=+$('size').value,font=$('font').value,n=+$('natural').value/100,line=Math.max(36,size*1.55),paper=$('paper').value;let c,ctx,y,x;canvases=[];$('pages').replaceChildren();$('page').replaceChildren();function sheet(){c=document.createElement('canvas');c.width=794;c.height=1123;c.className='sheet';c.setAttribute('aria-label','Hoja manuscrita '+(canvases.length+1));ctx=c.getContext('2d');ctx.fillStyle=paper==='cream'?'#faf1d9':'#fffef9';ctx.fillRect(0,0,794,1123);ctx.lineWidth=.7;ctx.strokeStyle='#abc0d04d';if(paper==='lined'||paper==='grid'){for(let sy=82;sy<1070;sy+=line){ctx.beginPath();ctx.moveTo(35,sy+5);ctx.lineTo(759,sy+5);ctx.stroke()}if(paper==='grid')for(let sx=35;sx<760;sx+=line){ctx.beginPath();ctx.moveTo(sx,45);ctx.lineTo(sx,1070);ctx.stroke()}ctx.strokeStyle='#da9d9d66';ctx.beginPath();ctx.moveTo(64,35);ctx.lineTo(64,1080);ctx.stroke()}ctx.font=`${size}px ${font}`;ctx.fillStyle=$('ink').value;y=82;x=82;canvases.push(c);$('pages').append(c)}sheet();for(const paragraph of $('text').value.replace(/\r/g,'').split('\n')){const words=paragraph.split(/\s+/).filter(Boolean);for(const word of words){const width=ctx.measureText(word).width;if(x+width>715&&x>82){x=82;y+=line}if(y>1050)sheet();for(const ch of word){const w=ctx.measureText(ch).width;ctx.save();ctx.translate(x,y+(random()-.5)*n*3);ctx.rotate((random()-.5)*n*.065);ctx.globalAlpha=.83+random()*.17;ctx.fillText(ch,0,0);ctx.restore();x+=w}x+=ctx.measureText(' ').width}x=82;y+=line;if(canvases.length>150){$('status').textContent='Documento demasiado largo: reduce el texto (máximo 150 hojas).';break}}canvases.forEach((_,i)=>$('page').add(new Option(`Hoja ${i+1}`,i)));$('count').textContent=`${canvases.length} ${canvases.length===1?'hoja':'hojas'} · A4`}
$('generate').onclick=()=>render();$('shuffle').onclick=()=>{$('pages').dataset.seed=Date.now()>>>0;render()};for(const id of ['font','paper','ink','size','natural'])$(id).onchange=()=>render();$('png').onclick=()=>{const a=document.createElement('a');a.href=canvases[+$('page').value].toDataURL('image/png');a.download=`manuscrito-hoja-${+$('page').value+1}.png`;a.click()};$('print').onclick=()=>window.print();
$('pdf').onchange=async()=>{const file=$('pdf').files[0];if(!file)return;$('status').textContent='Leyendo PDF…';try{const doc=await pdfjs.getDocument({data:await file.arrayBuffer()}).promise;let pages=[];for(let p=1;p<=doc.numPages;p++){const content=await(await doc.getPage(p)).getTextContent();let text='',lastY=null;for(const item of content.items){if(!('str'in item))continue;const yy=item.transform[5];if(lastY!==null&&Math.abs(yy-lastY)>5)text+='\n';text+=item.str+(item.hasEOL?'\n':' ');lastY=yy}pages.push(text.trim());$('status').textContent=`Leyendo página ${p} de ${doc.numPages}…`}const result=pages.join('\n\n');if(!result.trim())throw new Error('Este PDF no contiene texto extraíble. Si es un escaneo, necesita OCR.');$('text').value=result;await render();$('status').textContent=`Texto de ${doc.numPages} páginas importado. Revísalo antes de exportar.`;await doc.destroy()}catch(e){$('status').textContent=e.message||'No se pudo leer el PDF.'}};
render();
